engine.analyze:
function analyze(input, providers) {
  var docText = String((input && input.docText) || "");
  var ooxml = String((input && input.ooxml) || "");
  var paragraphs = Array.isArray(input && input.paragraphs) ? input.paragraphs : [];
  var findings = [];   // { id, severity: "error"|"warn"|"info", category, title, detail, locateText }
  var skipped = [];    // { check, reason }
  var CAP = 25;        // per-category cap; overflow noted

  function snippet(idx, len) {
    var start = Math.max(0, idx - 30);
    var s = docText.slice(start, idx + len + 30).replace(/\s+/g, " ").trim();
    return s.slice(0, 240);
  }
  function push(cat, sev, title, detail, locateText) {
    findings.push({
      id: cat + "_" + findings.length,
      severity: sev, category: cat, title: title,
      detail: detail || "", locateText: locateText || "",
    });
  }
  function capNote(cat, total) {
    if (total > CAP) {
      push(cat, "info", "+" + (total - CAP) + " more not shown",
        "Fix the ones above and re-run.", "");
    }
  }

  // ── Defined terms ─────────────────────────────────────────────────
  // Definition shapes: quoted term followed by means/has-the-meaning,
  // and parenthetical (the "Term") / (each a "Term") / (collectively,
  // the "Terms").
  var defined = {};   // term → { count, firstIdx }
  function noteDef(term, idx) {
    term = term.trim();
    if (term.length < 3 || term.length > 60) return;
    if (!defined[term]) defined[term] = { count: 0, firstIdx: idx };
    defined[term].count++;
  }
  var reMeans = /["“]([A-Z][^"“”]{1,58})["”]\s*\)?\s*(?:shall\s+mean|means\b|shall\s+have\s+the\s+meaning|has\s+the\s+meaning)/g;
  var m;
  while ((m = reMeans.exec(docText)) !== null) noteDef(m[1], m.index);
  var reParen = /\(\s*(?:the|each(?:,?\s+an?)?|an?|collectively,?(?:\s+the)?|individually,?(?:\s+an?)?|together,?(?:\s+the)?|hereinafter,?(?:\s+the)?)?\s*["“]([A-Z][^"“”]{1,58})["”]\s*\)/g;
  while ((m = reParen.exec(docText)) !== null) noteDef(m[1], m.index);

  var termNames = Object.keys(defined);
  var dupCount = 0, unusedCount = 0;
  termNames.forEach(function (t) {
    var d = defined[t];
    if (d.count >= 2 && dupCount < CAP) {
      dupCount++;
      push("defined_terms", "warn", "“" + t + "” defined " + d.count + " times",
        "Multiple definitions of the same term invite conflict — keep one.",
        t);
    }
    // Usage = total occurrences minus definition occurrences. Substring
    // count is intentionally case-sensitive: defined terms are used
    // capitalized.
    var total = 0, at = docText.indexOf(t);
    while (at !== -1) { total++; at = docText.indexOf(t, at + t.length); }
    if (total <= d.count && unusedCount < CAP) {
      unusedCount++;
      push("defined_terms", "warn", "“" + t + "” defined but never used",
        "Dead weight, or the body text uses a different name for it.",
        t);
    }
  });
  capNote("defined_terms", dupCount);
  capNote("defined_terms", unusedCount);

  // Used-but-never-defined (heuristic, deliberately narrow): capitalized
  // phrases ending in a common defined-term head noun, occurring 2+
  // times, with no matching definition. Head-noun anchor kills most
  // proper-noun noise; findings are labeled "possible".
  var HEADS = ["Date", "Period", "Term", "Fee", "Fees", "Information", "Services",
    "Service", "Products", "Product", "Materials", "Party", "Parties", "Notice",
    "Affiliate", "Affiliates", "Laws", "Law", "Claim", "Claims", "Losses", "Data",
    "Software", "Deliverables", "Deliverable", "Territory", "Purpose", "Price",
    "Order", "Work", "Confidential Information", "Effective Date"];
  var candCounts = {};
  var reCand = /(?:[a-z0-9],?;?\s)((?:[A-Z][A-Za-z0-9'\-]+\s){0,3}[A-Z][A-Za-z0-9'\-]+)/g;
  while ((m = reCand.exec(docText)) !== null) {
    var phrase = m[1].trim();
    var lastWord = phrase.split(/\s+/).pop();
    if (HEADS.indexOf(lastWord) === -1) continue;
    if (phrase.split(/\s+/).length < 2 && HEADS.indexOf(phrase) === -1) continue;
    candCounts[phrase] = (candCounts[phrase] || 0) + 1;
  }
  var undefCount = 0;
  Object.keys(candCounts).forEach(function (p) {
    if (candCounts[p] < 2 || undefCount >= CAP) return;
    if (defined[p]) return;
    // Substring tolerance: "Renewal Term" is fine if "Term" is defined
    // and vice versa is NOT assumed — only exact matches clear a phrase.
    undefCount++;
    push("defined_terms", "info", "Possible undefined term: “" + p + "”",
      "Used " + candCounts[p] + " times, capitalized like a defined term, but no definition found.",
      p);
  });
  capNote("defined_terms", undefCount);

  // ── Cross-references ──────────────────────────────────────────────
  // Section inventory comes from text-visible numbering at paragraph
  // starts. Word's API hides automatic list numbering from .text, so
  // when almost no numbering is visible the check reports itself
  // skipped instead of spraying false positives.
  var sectionSet = {};
  var subVisible = false;
  paragraphs.forEach(function (p) {
    var t = String((p && p.text) || "");
    var mm = t.match(/^\s*(?:Section|SECTION|Article|ARTICLE|§)?\s*(\d+(?:\.\d+)*)[.)\s]/);
    if (mm) {
      sectionSet[mm[1]] = true;
      if (mm[1].indexOf(".") !== -1) subVisible = true;
    }
  });
  var sectionCount = Object.keys(sectionSet).length;
  if (sectionCount < 3) {
    skipped.push({
      check: "Cross-references",
      reason: "Almost no section numbering is text-visible (the document likely uses Word automatic numbering, which the API hides). Skipped to avoid false positives.",
    });
  } else {
    var reRef = /(?:Section|Sections|Sec\.|§)\s*(\d+(?:\.\d+)*)/g;
    var missing = {}, refCount = 0;
    while ((m = reRef.exec(docText)) !== null) {
      var ref = m[1];
      if (sectionSet[ref]) continue;
      // Only flag subsection refs when subsection numbering is provably
      // text-visible somewhere; otherwise auto-subnumbering hides them.
      if (ref.indexOf(".") !== -1 && !subVisible) continue;
      if (!missing[ref]) {
        missing[ref] = true;
        refCount++;
        if (refCount <= CAP) {
          push("cross_refs", "error", "Reference to Section " + ref + " — not found",
            "No section with this number is visible in the document. Renumbering may have broken this reference.",
            snippet(m.index, m[0].length));
        }
      }
    }
    capNote("cross_refs", refCount);
  }

  // ── Drafting artifacts ────────────────────────────────────────────
  var artCount = 0;
  function art(sev, title, detail, idx, len) {
    artCount++;
    if (artCount <= CAP) push("artifacts", sev, title, detail, snippet(idx, len));
  }
  var reBracket = /\[([^\]\n]{1,80})\]/g;
  while ((m = reBracket.exec(docText)) !== null) {
    if (/^\d+$/.test(m[1].trim())) continue;   // bare [1] — citation/footnote artifact, skip
    art("error", "Bracketed placeholder: [" + m[1].slice(0, 40) + (m[1].length > 40 ? "…" : "") + "]",
      "Square brackets usually mean an unresolved drafting decision.", m.index, m[0].length);
  }
  var reTbd = /\b(TBD|TBC|NTD|TO BE (?:DETERMINED|PROVIDED|AGREED|CONFIRMED)|NOTE TO DRAFT)\b/gi;
  while ((m = reTbd.exec(docText)) !== null) {
    art("error", "Placeholder text: " + m[1].toUpperCase(),
      "Unfinished drafting marker.", m.index, m[0].length);
  }
  var reBlank = /_{4,}/g;
  while ((m = reBlank.exec(docText)) !== null) {
    art("warn", "Blank line (____)",
      "Fill-in blank still empty.", m.index, m[0].length);
  }
  capNote("artifacts", artCount);

  // OOXML-level artifacts — counts only (locate isn't text-searchable).
  if (ooxml) {
    var hl = (ooxml.match(/<w:highlight\s+w:val="(?!none)/g) || []).length;
    if (hl) push("artifacts", "warn", hl + " highlighted run" + (hl === 1 ? "" : "s") + " in the document",
      "Highlighting usually marks open items. Word: Home → Find → Advanced Find → Format → Highlight.", "");
    var ins = (ooxml.match(/<w:ins\b/g) || []).length;
    var del = (ooxml.match(/<w:del\b/g) || []).length;
    if (ins + del) push("artifacts", "warn", (ins + del) + " tracked change" + (ins + del === 1 ? "" : "s") + " still pending",
      "Accept or reject all tracked changes before execution.", "");
    var cm = (ooxml.match(/<w:commentReference\b/g) || []).length;
    if (cm) push("artifacts", "info", cm + " margin comment" + (cm === 1 ? "" : "s") + " present",
      "Resolve and delete comments before the document leaves the building.", "");
  } else {
    skipped.push({ check: "Highlight / tracked-change / comment counts", reason: "Document OOXML unavailable on this read." });
  }

  // ── Exhibits & schedules ──────────────────────────────────────────
  var exRefs = {};
  var reEx = /\b(Exhibit|Schedule|Annex|Appendix)\s+([A-Z]{1,2}\b|\d{1,2}\b)/g;
  while ((m = reEx.exec(docText)) !== null) {
    exRefs[m[1] + " " + m[2]] = m.index;
  }
  Object.keys(exRefs).forEach(function (label) {
    var reHead = new RegExp("^\\s*" + label.replace(/\s+/, "\\s+") + "\\b", "m");
    // A heading-like occurrence (start of line) counts as "present".
    if (!reHead.test(docText)) {
      push("exhibits", "info", label + " referenced — not found in this document",
        "May be attached separately; verify it exists before signature.",
        snippet(exRefs[label], label.length));
    }
  });

  // ── Result contract ───────────────────────────────────────────────
  var errors = findings.filter(function (f) { return f.severity === "error"; }).length;
  var warns = findings.filter(function (f) { return f.severity === "warn"; }).length;
  return Promise.resolve({
    findings: findings,
    skipped: skipped,
    counts: { total: findings.length, errors: errors, warnings: warns, definedTerms: termNames.length, sections: sectionCount },
    overview: errors + " error" + (errors === 1 ? "" : "s") + ", " + warns + " warning" + (warns === 1 ? "" : "s") +
      " · " + termNames.length + " defined terms",
    provenance: {
      kernelVersion: (typeof window !== "undefined" && window.eli && window.eli.kernelVersion) || "v3",
      toolVersion: "v1.0",
      docHash: (input && input.docHash) || null,
      timestamp: Date.now(),
    },
  });
}

jsonTools.init:
function init(eli) {
  if (!eli || !eli.host || !eli.storage) return;
  var bundle = eli.tools && eli.tools._loaded && eli.tools._loaded.integrity_scanner;
  if (!bundle) return;
  var efns = bundle._eliEngineFns || {};
  var analyze = efns.analyze;

  var CAT_META = {
    defined_terms: { icon: "📖", label: "Defined terms" },
    cross_refs:    { icon: "🔗", label: "Cross-references" },
    artifacts:     { icon: "🧹", label: "Drafting artifacts" },
    exhibits:      { icon: "📎", label: "Exhibits & schedules" },
  };
  var SEV_META = {
    error: { chip: "ERROR", bg: "#fee2e2", border: "#fca5a5", color: "#991b1b" },
    warn:  { chip: "WARN",  bg: "#fef3c7", border: "#fcd34d", color: "#92400e" },
    info:  { chip: "INFO",  bg: "#e0f2fe", border: "#7dd3fc", color: "#075985" },
  };

  function _esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }

  function _readDoc() {
    return eli.host.runRaw("integrity:read", function (context) {
      var body = context.document.body;
      body.load("text");
      var paras = body.paragraphs;
      paras.load("items/text");
      var ooxmlReq = body.getOoxml();
      return context.sync().then(function () {
        return {
          docText: String(body.text || ""),
          ooxml: String((ooxmlReq && ooxmlReq.value) || ""),
          paragraphs: (paras.items || []).map(function (p, i) {
            return { index: i, text: String(p.text || "") };
          }),
        };
      });
    });
  }

  // Locate: exact search on the finding's snippet (≤250 chars — Word's
  // search cap), select + scroll. Findings without locateText (OOXML
  // count findings) don't render the button.
  function _locate(text) {
    var q = String(text || "").trim().substring(0, 250);
    if (q.length < 3) return Promise.resolve(false);
    return eli.host.runRaw("integrity:locate", function (context) {
      var res = context.document.body.search(q, {
        matchCase: false, matchWholeWord: false, ignorePunct: true, ignoreSpace: true,
      });
      res.load("items");
      return context.sync().then(function () {
        if (!res.items || !res.items.length) return false;
        res.items[0].select();
        res.items[0].scrollIntoView();
        return context.sync().then(function () { return true; });
      });
    }).catch(function () { return false; });
  }

  function _renderFindingRow(f) {
    var sev = SEV_META[f.severity] || SEV_META.info;
    return '<div class="_is_row">' +
      '<span class="_is_chip" style="background:' + sev.bg + ';border-color:' + sev.border + ';color:' + sev.color + ';">' + sev.chip + '</span>' +
      '<span class="_is_row_text">' +
        '<span class="_is_row_title">' + _esc(f.title) + '</span>' +
        (f.detail ? '<span class="_is_row_detail">' + _esc(f.detail) + '</span>' : '') +
      '</span>' +
      (f.locateText
        ? '<button type="button" class="_is_locate" data-locate="' + _esc(f.locateText) + '">Locate</button>'
        : '') +
    '</div>';
  }

  function _renderResults(mount, result) {
    var counts = result.counts || {};
    var byCat = {};
    (result.findings || []).forEach(function (f) {
      (byCat[f.category] = byCat[f.category] || []).push(f);
    });
    var catHtml = Object.keys(CAT_META).map(function (cat) {
      var items = byCat[cat] || [];
      var meta = CAT_META[cat];
      var body = items.length
        ? items.map(_renderFindingRow).join("")
        : '<div class="_is_clean">✓ Clean</div>';
      return '<section class="_is_card">' +
        '<div class="_is_card_head">' + meta.icon + ' ' + meta.label +
          '<span class="_is_card_count">' + items.length + '</span></div>' +
        body +
      '</section>';
    }).join("");
    var skippedHtml = (result.skipped || []).length
      ? '<section class="_is_card _is_card_skipped">' +
          '<div class="_is_card_head">⏭ Checks skipped</div>' +
          result.skipped.map(function (s) {
            return '<div class="_is_row"><span class="_is_row_text"><span class="_is_row_title">' + _esc(s.check) + '</span>' +
              '<span class="_is_row_detail">' + _esc(s.reason) + '</span></span></div>';
          }).join("") +
        '</section>'
      : "";
    mount.innerHTML =
      '<div class="_is_summary">' +
        '<span class="_is_sum_item _is_sum_err">' + (counts.errors || 0) + ' errors</span>' +
        '<span class="_is_sum_item _is_sum_warn">' + (counts.warnings || 0) + ' warnings</span>' +
        '<span class="_is_sum_item">' + (counts.definedTerms || 0) + ' defined terms</span>' +
        '<span class="_is_sum_item">' + (counts.sections || 0) + ' visible sections</span>' +
      '</div>' +
      catHtml + skippedHtml;
    Array.prototype.forEach.call(mount.querySelectorAll("._is_locate"), function (btn) {
      btn.onclick = function () {
        btn.disabled = true;
        _locate(btn.getAttribute("data-locate")).then(function (ok) {
          btn.disabled = false;
          if (!ok && typeof showToast === "function") {
            showToast("Couldn't find that text — it may have changed since the scan. Re-run.", "warn");
          }
        });
      };
    });
  }

  function _copyReport(result) {
    var lines = ["ELI INTEGRITY SCAN — " + new Date().toLocaleString(), ""];
    lines.push(result.overview || "");
    lines.push("");
    (result.findings || []).forEach(function (f) {
      lines.push("[" + f.severity.toUpperCase() + "] " + f.title + (f.detail ? " — " + f.detail : ""));
    });
    (result.skipped || []).forEach(function (s) {
      lines.push("[SKIPPED] " + s.check + " — " + s.reason);
    });
    var text = lines.join("\n");
    var ta = document.createElement("textarea");
    ta.value = text;
    ta.style.cssText = "position:fixed;left:-9999px;opacity:0;";
    document.body.appendChild(ta);
    ta.select();
    var ok = false;
    try { ok = document.execCommand("copy"); } catch (_e) {}
    document.body.removeChild(ta);
    if (typeof showToast === "function") {
      showToast(ok ? "Report copied to clipboard" : "Copy failed — select and copy manually", ok ? "ok" : "err");
    }
  }

  function _runScan(mount, statusEl) {
    if (typeof analyze !== "function") {
      mount.innerHTML = '<div class="_is_error">Engine missing — reinstall the tool bundle.</div>';
      return;
    }
    statusEl.textContent = "Scanning…";
    var t0 = Date.now();
    _readDoc().then(function (read) {
      return analyze({
        docText: read.docText,
        ooxml: read.ooxml,
        paragraphs: read.paragraphs,
      });
    }).then(function (result) {
      statusEl.textContent = "Scanned in " + ((Date.now() - t0) / 1000).toFixed(1) + "s · " + (result.overview || "");
      _renderResults(mount, result);
      var copyBtn = document.getElementById("_is_copy");
      if (copyBtn) copyBtn.onclick = function () { _copyReport(result); };
      try { eli.log.event("tool", "integrity_scan_complete", result.counts || {}); } catch (_e) {}
    }).catch(function (err) {
      statusEl.textContent = "";
      mount.innerHTML = '<div class="_is_error">Scan failed: ' + _esc(err && err.message || "unknown") + '</div>';
    });
  }

  function _launch() {
    try { if (eli.stats && eli.stats.record) eli.stats.record("appOpenedIntegrity"); } catch (_e) {}
    var out = window.eli.ui && typeof window.eli.ui.claimOutput === "function"
      ? window.eli.ui.claimOutput()
      : document.getElementById("output");
    if (!out) return;
    out.classList.add("eli-view-enter");
    out.innerHTML =
      '<div class="_is_root">' +
        '<div class="_is_header">' +
          '<div>' +
            '<div class="_is_title">🧰 Integrity Scan</div>' +
            '<div class="_is_subtitle">Deterministic pre-send checks — no AI, runs offline</div>' +
          '</div>' +
          '<div class="_is_header_actions">' +
            '<button type="button" id="_is_rescan" class="_is_btn">↻ Re-scan</button>' +
            '<button type="button" id="_is_copy" class="_is_btn">📋 Copy report</button>' +
          '</div>' +
        '</div>' +
        '<div class="_is_status" id="_is_status"></div>' +
        '<div class="_is_body" id="_is_results"><div class="_is_clean">Reading document…</div></div>' +
      '</div>';
    var mount = document.getElementById("_is_results");
    var statusEl = document.getElementById("_is_status");
    document.getElementById("_is_rescan").onclick = function () { _runScan(mount, statusEl); };
    _runScan(mount, statusEl);   // auto-run on open
  }

  if (eli.register) {
    eli.register({
      tile: {
        app_integrity_scanner: eli.events && eli.events.guard
          ? eli.events.guard(function () { _launch(); }, "integrity_scanner.tile")
          : function () { _launch(); },
      },
    });
  }
  if (eli.log && eli.log.event) eli.log.event("tool", "integrity_scanner_initialized", {});
}

jsonTools.css:
/* Integrity Scan — light root over the dark dashboard, navy/gold header,
   squared corners throughout. */

#output:has(._is_root) { background: #f8fafc; }

._is_root {
  flex: 1 0 auto;
  background: #f8fafc;
  font-family: Inter, "Segoe UI", system-ui, -apple-system, sans-serif;
  color: #0f172a;
  min-height: 100%;
}

._is_header {
  background: linear-gradient(120deg, #12346f, #1d4a94 44%, #3b82f6);
  border-bottom: 2px solid #d4a237;
  color: #fff;
  padding: 13px 16px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}
._is_title { font-size: 16px; font-weight: 800; letter-spacing: 0.02em; }
._is_subtitle { font-size: 11px; font-weight: 500; color: #dbeafe; margin-top: 2px; }
._is_header_actions { display: flex; gap: 6px; flex-shrink: 0; }

._is_btn {
  font: 700 11px/1.2 Inter, sans-serif;
  letter-spacing: 0.04em;
  padding: 6px 11px;
  border-radius: 0;
  cursor: pointer;
  border: 1px solid rgba(219, 234, 254, 0.5);
  background: rgba(255, 255, 255, 0.1);
  color: #fff;
}
._is_btn:hover { background: rgba(255, 255, 255, 0.2); }
._is_btn:disabled { opacity: 0.55; cursor: default; }

._is_status {
  padding: 6px 16px;
  font: 600 11px/1.4 Inter, sans-serif;
  color: #475569;
  background: #eef2f7;
  border-bottom: 1px solid #e2e8f0;
  min-height: 16px;
}

._is_body { padding: 12px 14px; display: flex; flex-direction: column; gap: 10px; }

._is_summary { display: flex; gap: 8px; flex-wrap: wrap; }
._is_sum_item {
  font: 700 11px/1.2 Inter, sans-serif;
  padding: 5px 10px;
  background: #fff;
  border: 1px solid #cbd5e1;
  color: #334155;
}
._is_sum_err  { border-color: #fca5a5; color: #991b1b; background: #fef2f2; }
._is_sum_warn { border-color: #fcd34d; color: #92400e; background: #fffbeb; }

._is_card { background: #fff; border: 1px solid #e2e8f0; border-radius: 0; }
._is_card_head {
  font: 800 11px/1.2 Inter, sans-serif;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: #1e40af;
  padding: 9px 12px;
  border-bottom: 1px solid #e2e8f0;
  background: #f8fafc;
  display: flex;
  align-items: center;
  gap: 6px;
}
._is_card_count {
  margin-left: auto;
  font: 800 11px/1.2 Consolas, monospace;
  color: #475569;
  background: #f1f5f9;
  border: 1px solid #e2e8f0;
  padding: 2px 8px;
}
._is_card_skipped ._is_card_head { color: #92400e; }

._is_row {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  padding: 8px 12px;
  border-bottom: 1px solid #f1f5f9;
}
._is_row:last-child { border-bottom: none; }
._is_chip {
  flex-shrink: 0;
  font: 800 9px/1.2 Inter, sans-serif;
  letter-spacing: 0.06em;
  padding: 3px 7px;
  border: 1px solid;
  border-radius: 0;
  margin-top: 1px;
}
._is_row_text { flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 1px; }
._is_row_title { font: 600 12px/1.4 Inter, sans-serif; color: #0f172a; word-break: break-word; }
._is_row_detail { font: 400 11px/1.4 Inter, sans-serif; color: #64748b; }

._is_locate {
  flex-shrink: 0;
  font: 700 10px/1.2 Inter, sans-serif;
  letter-spacing: 0.04em;
  padding: 4px 10px;
  border-radius: 0;
  cursor: pointer;
  border: 1px solid #cbd5e1;
  background: linear-gradient(180deg, #ffffff 0%, #f1f5f9 100%);
  color: #1e40af;
}
._is_locate:hover { border-color: #1e40af; }
._is_locate:disabled { opacity: 0.55; cursor: default; }

._is_clean {
  padding: 10px 12px;
  font: 600 11px/1.4 Inter, sans-serif;
  color: #166534;
}
._is_error {
  padding: 12px;
  font: 600 12px/1.5 Inter, sans-serif;
  color: #991b1b;
  background: #fef2f2;
  border: 1px solid #fca5a5;
}
